#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

TreeNode* newNode(int val) {
    TreeNode* n = (TreeNode*)malloc(sizeof(TreeNode));
    n->val = val; n->left = NULL; n->right = NULL;
    return n;
}

/* Reads input of the form [[1,2,null,3]]. */
TreeNode* parseTree(const char* line) {
    const char* p = strchr(line, '[');
    if (!p) return NULL;
    p++;
    if (*p == '[') p++; /* unwrap outer argument array */
    TreeNode** nodes = (TreeNode**)malloc(101 * sizeof(TreeNode*));
    int count = 0, cap = 101;
    while (*p && *p != ']') {
        while (*p == ' ' || *p == ',') p++;
        if (*p == ']') break;
        if (strncmp(p, "null", 4) == 0) {
            nodes[count++] = NULL; p += 4;
        } else {
            char* end;
            long v = strtol(p, &end, 10);
            nodes[count++] = newNode((int)v);
            p = end;
        }
        if (count >= cap) break;
    }
    if (count == 0 || nodes[0] == NULL) { free(nodes); return NULL; }

    int child = 1;
    for (int i = 0; i < count && child < count; i++) {
        if (nodes[i] == NULL) continue;
        if (child < count) nodes[i]->left = nodes[child++];
        if (child < count) nodes[i]->right = nodes[child++];
    }
    TreeNode* root = nodes[0];
    free(nodes);
    return root;
}

void freeTree(TreeNode* root) {
    if (!root) return;
    freeTree(root->left); freeTree(root->right); free(root);
}

/* Return a malloc'ed array; caller frees it. */
int* postorderTraversal(TreeNode* root, int* returnSize) {
    int* result = (int*)malloc(100 * sizeof(int));
    *returnSize = 0;
    if (!root) return result;

    TreeNode* stack[100];
    TreeNode* lastVisited = NULL;
    int top = 0;
    TreeNode* cur = root;

    while (cur || top > 0) {
        while (cur) {
            stack[top++] = cur;
            cur = cur->left;
        }
        TreeNode* peek = stack[top - 1];
        if (peek->right && lastVisited != peek->right) {
            cur = peek->right;
        } else {
            result[(*returnSize)++] = peek->val;
            lastVisited = stack[--top];
        }
    }
    return result;
}

