class Solution {
public:
    vector<int> postorderTraversal(TreeNode* root) {
        vector<int> result;
        vector<TreeNode*> st;
        TreeNode* lastVisited = nullptr;
        TreeNode* cur = root;

        while (cur || !st.empty()) {
            while (cur) {
                st.push_back(cur);
                cur = cur->left;
            }
            TreeNode* node = st.back();
            if (node->right && lastVisited != node->right) {
                cur = node->right;
            } else {
                result.push_back(node->val);
                lastVisited = node;
                st.pop_back();
            }
        }
        return result;
    }
};

