public class Main {
    static TreeNode parseTree(String s) {
        s = s.trim();
        int l = s.indexOf('['), r = s.lastIndexOf(']');
        if (l < 0 || r < 0 || r <= l) return null;
        int innerStart = s.indexOf('[', l + 1);
        if (innerStart < 0 || innerStart >= r) return null;
        String inner = s.substring(innerStart + 1, r - 1);
        if (inner.trim().isEmpty()) return null;

        String[] parts = inner.split("\\s*,\\s*");
        List<TreeNode> nodes = new ArrayList<>();
        for (String p : parts) {
            p = p.trim();
            nodes.add(p.equals("null") ? null : new TreeNode(Integer.parseInt(p)));
        }
        if (nodes.isEmpty() || nodes.get(0) == null) return null;

        int child = 1;
        for (int i = 0; i < nodes.size() && child < nodes.size(); i++) {
            TreeNode node = nodes.get(i);
            if (node == null) continue;
            node.left = nodes.get(child++);
            if (child < nodes.size()) node.right = nodes.get(child++);
        }
        return nodes.get(0);
    }

    static void printList(List<Integer> result) {
        System.out.print("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) System.out.print(",");
            System.out.print(result.get(i));
        }
        System.out.println("]");
    }

